        // makeEvolutionsEasier
        json.put("makeEvolutionsEasier", settings.isMakeEvolutionsEasier());

        // removeTimeBasedEvolutions
        json.put("removeTimeBasedEvolutions", settings.isRemoveTimeBasedEvolutions());

        // evosAllowAltFormes -- Declared alongside the other Evolutions-tab fields in Settings.java, but its setter is interleaved w
