        // raceMode
        json.put("raceMode", settings.isRaceMode());

        // banIrregularAltFormes
        json.put("banIrregularAltFormes", settings.isBanIrregularAltFormes());

        // blockBrokenMoves -- Convenience setter: internally sets blockBrokenMovesetMoves, blockBrokenTMMoves, and blockBrokenTuto
        // blockBrokenMoves intentionally skipped — write-only convenience setter, no getter (see NO_GETTER_FIELDS)

        // limitPokemon -- Enables the generation-restriction pool defined by currentRestrictions (GenRestrictions).
        json.put("limitPokemon", settings.isLimitPokemon());

        // baseStatisticsMod -- Java setter signature is `setBaseStatisticsMod(boolean... bools)`. Internally it calls Settings.getE
