        json.put("assignEvoStatsRandomly", settings.isAssignEvoStatsRandomly());

        // updateBaseStats
        json.put("updateBaseStats", settings.isUpdateBaseStats());

        // updateBaseStatsToGeneration -- Generation number to update base stats to; only relevant when updateBaseStats is true.
        json.put("updateBaseStatsToGeneration", settings.getUpdateBaseStatsToGeneration());

        // standardizeEXPCurves
